problems.solution:
#include <stdio.h>

#define MAXSIZE 20

/* 对 r[1..n] 按增量 dk 作一趟缩小增量的直接插入排序，r[0] 作暂存 */
void ShellInsert(int r[], int n, int dk) {
    int i, j;

    for (i = dk + 1; i <= n; i++) {
        if (r[i] < r[i - dk]) {
            r[0] = r[i];
            for (j = i - dk; j > 0 && r[0] < r[j]; j -= dk)
                r[j + dk] = r[j];
            r[j + dk] = r[0];
        }
    }
}

void ShellSort(int r[], int n, int dlta[], int t) {
    int k, i;

    for (k = 0; k < t; k++) {
        ShellInsert(r, n, dlta[k]);
        for (i = 1; i <= n; i++)
            printf("%d ", r[i]);
        printf("\n");
    }
}

int main(void) {
    int r[MAXSIZE + 1], dlta[10];
    int n, t, i;

    if (scanf("%d", &n) != 1 || n < 0 || n > MAXSIZE)
        return 1;
    for (i = 1; i <= n; i++)
        if (scanf("%d", &r[i]) != 1)
            return 1;
    r[0] = 0;
    if (scanf("%d", &t) != 1 || t < 1 || t > 10)
        return 1;
    for (i = 0; i < t; i++)
        if (scanf("%d", &dlta[i]) != 1)
            return 1;
    ShellSort(r, n, dlta, t);
    return 0;
}

