#include <stdio.h>

#define MAXSIZE 20

int main(void) {
    int r[MAXSIZE + 1] = {0, 49, 38, 65, 97, 76, 13, 27};
    int n = 7, i, j, low, high, mid, cmp = 0;

    for (i = 2; i <= n; i++) {
        r[0] = r[i];
        low = 1;
        high = i - 1;
        while (low <= high) {
            mid = (low + high) / 2;
            cmp++;
            if (r[0] < r[mid])
                high = mid - 1;
            else
                low = mid + 1;
        }
        for (j = i - 1; j >= high + 1; j--)
            r[j + 1] = r[j];
        r[high + 1] = r[0];
    }
    for (j = 1; j <= n; j++)
        printf("%d ", r[j]);
    printf("\n%d\n", cmp);
    return 0;
}
