#include <stdio.h>

int a[8] = {49, 38, 65, 97, 76, 13, 27, 49};

int Partition(int low, int high) {
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot)
            high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot)
            low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

int main(void) {
    int i, p = Partition(0, 7);
    printf("pivotpos=%d\n", p);
    for (i = 0; i < 8; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}
