#include <stdio.h>

void BubbleSort(int a[], int n) {
    int i, j, t, flag;
    for (i = 0; i < n - 1; i++) {
        flag = 0;
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                flag = 1;
            }
        if (flag == 0)
            break;
    }
}
int main(void) {
    int a[100], n, i;
    if (scanf("%d", &n) != 1)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    BubbleSort(a, n);

    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

