#include <stdio.h>

void Merge(int a[], int b[], int low, int mid, int high) {
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high) {
        if (a[i] <= a[j])
            b[k++] = a[i++];
        else
            b[k++] = a[j++];
    }
    while (i <= mid)
        b[k++] = a[i++];
    while (j <= high)
        b[k++] = a[j++];
}

void MergePass(int a[], int b[], int n, int len) {
    int i = 0, j;
    while (i + 2 * len - 1 < n) {
        Merge(a, b, i, i + len - 1, i + 2 * len - 1);
        i = i + 2 * len;
    }
    if (i + len - 1 < n - 1)
        Merge(a, b, i, i + len - 1, n - 1);
    else
        for (j = i; j < n; j++)
            b[j] = a[j];
}

int main(void) {
    int a[9] = {50, 10, 90, 30, 70, 40, 80, 60, 20};
    int b[9];
    int n = 9, len, i;
    for (len = 1; len < n; len = len * 2) {
