problems.stem:
写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
5 49 38 65 97 76
```

程序：
```c
#include <stdio.h>
#define MAXN 100
int cmp = 0, swaps = 0;
void bubble(int a[], int n) {
    int i, j, t, flag;
    for (i = 0; i < n - 1; i++) {
        flag = 0;
        for (j = 0; j < n - 1 - i; j++) {
            cmp++;
            if (a[j] > a[j + 1]) { t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; swaps++; flag = 1; }
        }
        if (!flag) break;
    }
}
int main(void) {
    int a[MAXN], n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    bubble(a, n);
    printf("结果:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n比较=%d 交换=%d\n", cmp, swaps);
    return 0;
}
```

