problems.stem:
写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
5 49 38 65 97 76
```

程序：
```c
#include <stdio.h>
#define MAXN 100
int cmp = 0, swp = 0;
void siftDown(int a[], int k, int n) {
    int t = a[k], child;
    while (k * 2 + 1 < n) {
        child = 2 * k + 1;
        if (child + 1 < n && a[child] < a[child + 1]) child++;
        cmp++;
        if (t >= a[child]) break;
        a[k] = a[child]; k = child;
    }
    a[k] = t;
}
void heapSort(int a[], int n) {
    int i, t;
    for (i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n);
    for (i = n - 1; i > 0; i--) { t = a[0]; a[0] = a[i]; a[i] = t; swp++; siftDown(a, 0, i); }
}
int main(void) {
    int a[MAXN], n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    heapSort(a, n);
    printf("结果:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n比较=%d 交换=%d\n", cmp, swp);
    return 0;
}
```

