```
10 49 38 65 97 76 13 27 49 55 4
```

程序：
```c
#include <stdio.h>
#define MAXN 100
int cmp = 0, mv = 0;
void shell(int a[], int n) {
    int d, i, j, t;
    for (d = n / 2; d > 0; d /= 2) {
        for (i = d; i < n; i++) {
            t = a[i];
            for (j = i - d; j >= 0 && a[j] > t; j -= d) { cmp++; a[j + d] = a[j]; mv++; }
            cmp++;
            a[j + d] = t; mv++;
        }
    }
}
int main(void) {
    int a[MAXN], n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    shell(a, n);
    printf("结果:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n比较=%d 移动=%d\n", cmp, mv);
    return 0;
}
```

