写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
9 49 38 65 97 76 13 27 49 55
```

程序：
```c
#include <stdio.h>
#define MAXN 100
int cmp = 0, mv = 0;
void merge(int a[], int lo, int mid, int hi) {
    int b[MAXN], i, j, k;
    for (i = lo; i <= hi; i++) b[i] = a[i];
    i = lo; j = mid + 1; k = lo;
    while (i <= mid && j <= hi) {
        cmp++;
        if (b[i] <= b[j]) { a[k++] = b[i++]; mv++; }
        else { a[k++] = b[j++]; mv++; }
    }
    while (i <= mid) { a[k++] = b[i++]; mv++; }
    while (j <= hi) { a[k++] = b[j++]; mv++; }
}
void ms(int a[], int lo, int hi) {
    if (lo >= hi) return;
    int mid = (lo + hi) / 2;
    ms(a, lo, mid); ms(a, mid + 1, hi); merge(a, lo, mid, hi);
}
int main(void) {
    int a[MAXN], n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    ms(a, 0, n - 1);
    printf("结果:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n比较=%d 移动=%d\n", cmp, mv);
    return 0;
}
```

